"""Core service surface for PowerRail.

The baseline reports process health; battery state-of-charge estimation is
served from :meth:`Service.estimate_soc`. Keep the public surface here
backward compatible and express all client failures as :class:`ApiError`.
"""

from __future__ import annotations

import math
from typing import Any

from . import __version__

DEFAULT_REST_CURRENT_A = 0.05
DEFAULT_REST_DURATION_S = 300.0
DEFAULT_OCV_WEIGHT = 0.2
DEFAULT_END_OF_LIFE_SOH = 0.8


class ApiError(Exception):
    """Client error carrying an HTTP status and a stable machine-readable code."""

    def __init__(self, status: int, code: str, message: str) -> None:
        super().__init__(message)
        self.status = status
        self.code = code
        self.message = message


def _is_finite_number(value: Any) -> bool:
    # ``bool`` is a subclass of ``int`` but is not a valid numeric reading.
    return (
        isinstance(value, (int, float))
        and not isinstance(value, bool)
        and math.isfinite(value)
    )


def _interpolate_ocv(voltage: float, points: list[tuple[float, float]]) -> float:
    """Linearly interpolate SoC from a voltage-sorted OCV curve.

    Voltages outside the curve resolve to the nearest endpoint.
    """
    first_voltage, first_soc = points[0]
    last_voltage, last_soc = points[-1]
    if voltage <= first_voltage:
        return first_soc
    if voltage >= last_voltage:
        return last_soc
    for (v0, s0), (v1, s1) in zip(points, points[1:]):
        if voltage <= v1:
            ratio = (voltage - v0) / (v1 - v0)
            return s0 + ratio * (s1 - s0)
    return last_soc  # pragma: no cover - unreachable for a sorted curve


class Service:
    """Stateless service surface: health reporting and SoC estimation."""

    name = "powerrail"
    version = __version__

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    def estimate_soc(self, payload: Any) -> dict[str, Any]:
        """Validate and run a coulomb-counting SoC estimate with OCV correction."""
        if not isinstance(payload, dict):
            raise ApiError(400, "invalid_json", "request body must be a JSON object")

        capacity = payload.get("capacity_ah")
        if not _is_finite_number(capacity) or capacity <= 0:
            raise ApiError(
                422, "invalid_capacity", "capacity_ah must be a positive finite number"
            )

        initial_soc = payload.get("initial_soc")
        if not _is_finite_number(initial_soc) or not 0 <= initial_soc <= 1:
            raise ApiError(
                422,
                "invalid_initial_soc",
                "initial_soc must be a finite number within [0, 1]",
            )

        samples = payload.get("samples")
        if not isinstance(samples, list) or not samples:
            raise ApiError(422, "invalid_samples", "samples must be a non-empty array")

        timestamps: list[float] = []
        previous_timestamp: float | None = None
        for sample in samples:
            if not isinstance(sample, dict):
                raise ApiError(
                    422,
                    "invalid_timestamp",
                    "each sample must be an object with a finite timestamp_s",
                )
            timestamp = sample.get("timestamp_s")
            if not _is_finite_number(timestamp):
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be a finite number"
                )
            if previous_timestamp is not None and timestamp <= previous_timestamp:
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be strictly increasing"
                )
            timestamps.append(timestamp)
            previous_timestamp = timestamp

        currents: list[float] = []
        voltages: list[float] = []
        for sample in samples:
            current = sample.get("current_a")
            voltage = sample.get("voltage_v")
            if not _is_finite_number(current) or not _is_finite_number(voltage):
                raise ApiError(
                    422,
                    "invalid_measurement",
                    "current_a and voltage_v must be finite numbers",
                )
            currents.append(current)
            voltages.append(voltage)

        ocv_points = self._parse_ocv_curve(payload.get("ocv_curve"))
        rest_current, rest_duration, ocv_weight = self._parse_options(payload)

        estimates: list[dict[str, Any]] = []
        soc = initial_soc
        rest_elapsed = 0.0
        capacity_seconds = capacity * 3600.0

        for index in range(len(samples)):
            timestamp = timestamps[index]
            if index == 0:
                estimates.append(
                    {"timestamp_s": timestamp, "soc": soc, "source": "coulomb"}
                )
                continue

            delta_time = timestamp - timestamps[index - 1]
            average_current = (currents[index - 1] + currents[index]) / 2.0
            soc_next = soc - average_current * delta_time / capacity_seconds
            if soc_next < 0.0:
                soc_next = 0.0
            elif soc_next > 1.0:
                soc_next = 1.0

            source = "coulomb"
            if ocv_points is not None:
                if (
                    abs(currents[index - 1]) <= rest_current
                    and abs(currents[index]) <= rest_current
                ):
                    rest_elapsed += delta_time
                else:
                    rest_elapsed = 0.0
                if rest_elapsed >= rest_duration:
                    ocv_soc = _interpolate_ocv(voltages[index], ocv_points)
                    soc_next = (
                        1.0 - ocv_weight
                    ) * soc_next + ocv_weight * ocv_soc
                    source = "ocv_corrected"

            soc = soc_next
            estimates.append(
                {"timestamp_s": timestamp, "soc": soc, "source": source}
            )

        return {"estimates": estimates, "final_soc": soc}

    def estimate_health(self, payload: Any) -> dict[str, Any]:
        """Estimate battery state of health and remaining cycle life."""
        if not isinstance(payload, dict):
            raise ApiError(400, "invalid_json", "request body must be a JSON object")

        nominal_capacity = payload.get("nominal_capacity_ah")
        if not _is_finite_number(nominal_capacity) or nominal_capacity <= 0:
            raise ApiError(
                422,
                "invalid_nominal_capacity",
                "nominal_capacity_ah must be a positive finite number",
            )

        measurements = payload.get("measurements")
        if not isinstance(measurements, list) or len(measurements) < 2:
            raise ApiError(
                422,
                "invalid_measurements",
                "measurements must be an array with at least two items",
            )
        for measurement in measurements:
            if not isinstance(measurement, dict):
                raise ApiError(
                    422,
                    "invalid_measurements",
                    "each measurement must be an object",
                )

        end_of_life_soh = payload.get("end_of_life_soh", DEFAULT_END_OF_LIFE_SOH)
        if (
            not _is_finite_number(end_of_life_soh)
            or not 0 <= end_of_life_soh <= 1
        ):
            raise ApiError(
                422,
                "invalid_end_of_life_soh",
                "end_of_life_soh must be a finite number within [0, 1]",
            )

        timestamps: list[float] = []
        previous_timestamp: float | None = None
        for measurement in measurements:
            timestamp = measurement.get("timestamp_s")
            if not _is_finite_number(timestamp):
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be a finite number"
                )
            if previous_timestamp is not None and timestamp <= previous_timestamp:
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be strictly increasing"
                )
            timestamps.append(timestamp)
            previous_timestamp = timestamp

        measured_capacities: list[float] = []
        for measurement in measurements:
            measured_capacity = measurement.get("measured_capacity_ah")
            if not _is_finite_number(measured_capacity) or measured_capacity <= 0:
                raise ApiError(
                    422,
                    "invalid_capacity_measurement",
                    "measured_capacity_ah must be a positive finite number",
                )
            measured_capacities.append(measured_capacity)

        cumulative_discharge: list[float] = []
        previous_throughput: float | None = None
        for measurement in measurements:
            throughput = measurement.get("cumulative_discharge_ah")
            if not _is_finite_number(throughput) or throughput < 0:
                raise ApiError(
                    422,
                    "invalid_throughput",
                    "cumulative_discharge_ah must be a non-negative finite number",
                )
            if previous_throughput is not None and throughput < previous_throughput:
                raise ApiError(
                    422,
                    "invalid_throughput",
                    "cumulative_discharge_ah must be non-decreasing",
                )
            cumulative_discharge.append(throughput)
            previous_throughput = throughput

        estimates: list[dict[str, Any]] = []
        for index in range(len(measurements)):
            soh = measured_capacities[index] / nominal_capacity
            if soh < 0.0:
                soh = 0.0
            elif soh > 1.0:
                soh = 1.0
            equivalent_cycles = cumulative_discharge[index] / nominal_capacity
            estimates.append(
                {
                    "timestamp_s": timestamps[index],
                    "soh": soh,
                    "equivalent_cycles": equivalent_cycles,
                }
            )

        latest_soh = estimates[-1]["soh"]
        consumed_cycles = estimates[-1]["equivalent_cycles"]

        remaining_cycles: float | None
        if latest_soh <= end_of_life_soh:
            remaining_cycles = 0
            projection_status = "end_of_life"
        else:
            first_soh = estimates[0]["soh"]
            first_cycles = estimates[0]["equivalent_cycles"]
            cycle_span = consumed_cycles - first_cycles
            soh_drop = first_soh - latest_soh
            if cycle_span > 0 and soh_drop > 0:
                degradation_rate = soh_drop / cycle_span
                remaining_cycles = (latest_soh - end_of_life_soh) / degradation_rate
                projection_status = "projected"
            else:
                remaining_cycles = None
                projection_status = "insufficient_trend"

        return {
            "estimates": estimates,
            "latest_soh": latest_soh,
            "consumed_cycles": consumed_cycles,
            "remaining_cycles": remaining_cycles,
            "projection_status": projection_status,
        }

    @staticmethod
    def _parse_ocv_curve(
        curve: Any,
    ) -> list[tuple[float, float]] | None:
        if curve is None:
            return None
        if not isinstance(curve, list) or len(curve) < 2:
            raise ApiError(
                422, "invalid_ocv_curve", "ocv_curve must contain at least two points"
            )
        points: list[tuple[float, float]] = []
        previous_voltage: float | None = None
        previous_soc: float | None = None
        for point in curve:
            if not isinstance(point, dict):
                raise ApiError(
                    422, "invalid_ocv_curve", "each OCV point must be an object"
                )
            voltage = point.get("voltage_v")
            soc = point.get("soc")
            if not _is_finite_number(voltage) or not _is_finite_number(soc):
                raise ApiError(
                    422,
                    "invalid_ocv_curve",
                    "OCV point voltage_v and soc must be finite numbers",
                )
            if not 0 <= soc <= 1:
                raise ApiError(
                    422, "invalid_ocv_curve", "OCV point soc must be within [0, 1]"
                )
            if previous_voltage is not None:
                if voltage <= previous_voltage:
                    raise ApiError(
                        422,
                        "invalid_ocv_curve",
                        "OCV point voltage_v must be strictly increasing",
                    )
                if soc < previous_soc:
                    raise ApiError(
                        422,
                        "invalid_ocv_curve",
                        "OCV point soc must be non-decreasing",
                    )
            points.append((voltage, soc))
            previous_voltage = voltage
            previous_soc = soc
        return points

    @staticmethod
    def _parse_options(payload: dict[str, Any]) -> tuple[float, float, float]:
        rest_current = payload.get("rest_current_a", DEFAULT_REST_CURRENT_A)
        rest_duration = payload.get("rest_duration_s", DEFAULT_REST_DURATION_S)
        ocv_weight = payload.get("ocv_weight", DEFAULT_OCV_WEIGHT)
        if (
            not _is_finite_number(rest_current)
            or not _is_finite_number(rest_duration)
            or not _is_finite_number(ocv_weight)
        ):
            raise ApiError(
                422,
                "invalid_options",
                "rest_current_a, rest_duration_s and ocv_weight must be finite numbers",
            )
        if rest_current < 0 or rest_duration < 0 or not 0 <= ocv_weight <= 1:
            raise ApiError(
                422,
                "invalid_options",
                "rest_current_a and rest_duration_s must be non-negative and "
                "ocv_weight must be within [0, 1]",
            )
        return rest_current, rest_duration, ocv_weight

"""HTTP entry point for PowerRail."""

from __future__ import annotations

import argparse
import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from .service import ApiError, Service

SOC_ROUTE = "/v1/battery/soc/estimate"
HEALTH_ROUTE = "/v1/battery/health/estimate"


def env_address() -> tuple[str, int]:
    raw = os.environ.get("POWERRAIL_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid POWERRAIL_ADDR: {raw!r}")
    return host, int(port)


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: dict) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def do_POST(self) -> None:
        if self.path not in (SOC_ROUTE, HEALTH_ROUTE):
            self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})
            return
        try:
            length = int(self.headers.get("Content-Length", 0))
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            payload = json.loads(raw.decode("utf-8")) if raw else None
        except (json.JSONDecodeError, UnicodeDecodeError):
            self.send_json(
                400, {"error": {"code": "invalid_json", "message": "request body must be valid JSON"}}
            )
            return
        try:
            if self.path == SOC_ROUTE:
                result = self.service.estimate_soc(payload)
            else:
                result = self.service.estimate_health(payload)
        except ApiError as exc:
            self.send_json(
                exc.status, {"error": {"code": exc.code, "message": exc.message}}
            )
            return
        self.send_json(200, result)

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def main() -> int:
    parser = argparse.ArgumentParser(prog="powerrail.server", description="电源与能耗管理平台")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"PowerRail listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import json
import threading
import unittest
import urllib.error
import urllib.request
from http.server import ThreadingHTTPServer

from powerrail.server import HEALTH_ROUTE, SOC_ROUTE, Handler
from powerrail.service import ApiError, Service


def base_request(**overrides):
    payload = {
        "nominal_capacity_ah": 100.0,
        "measurements": [
            {"timestamp_s": 0, "measured_capacity_ah": 100.0, "cumulative_discharge_ah": 0.0},
            {
                "timestamp_s": 100,
                "measured_capacity_ah": 90.0,
                "cumulative_discharge_ah": 100.0,
            },
        ],
    }
    payload.update(overrides)
    return payload


class HealthEstimationTest(unittest.TestCase):
    def setUp(self) -> None:
        self.service = Service()

    def test_per_item_estimates_match_measurements_in_order(self) -> None:
        result = self.service.estimate_health(base_request())
        estimates = result["estimates"]
        self.assertEqual(
            [item["timestamp_s"] for item in estimates], [0, 100]
        )
        self.assertAlmostEqual(estimates[0]["soh"], 1.0)
        self.assertAlmostEqual(estimates[0]["equivalent_cycles"], 0.0)
        self.assertAlmostEqual(estimates[1]["soh"], 0.9)
        self.assertAlmostEqual(estimates[1]["equivalent_cycles"], 1.0)
        self.assertAlmostEqual(result["latest_soh"], 0.9)
        self.assertAlmostEqual(result["consumed_cycles"], 1.0)

    def test_soh_is_clamped_to_unit_range(self) -> None:
        payload = base_request(
            measurements=[
                {
                    "timestamp_s": 0,
                    "measured_capacity_ah": 120.0,
                    "cumulative_discharge_ah": 0.0,
                },
                {
                    "timestamp_s": 10,
                    "measured_capacity_ah": 0.5,
                    "cumulative_discharge_ah": 50.0,
                },
            ]
        )
        estimates = self.service.estimate_health(payload)["estimates"]
        self.assertEqual(estimates[0]["soh"], 1.0)
        self.assertAlmostEqual(estimates[1]["soh"], 0.005)

    def test_projection_extrapolates_degradation_linearly(self) -> None:
        # soh drops 0.1 over one equivalent cycle -> 0.1 per cycle;
        # 0.9 down to the 0.8 threshold leaves one cycle.
        result = self.service.estimate_health(base_request())
        self.assertEqual(result["projection_status"], "projected")
        self.assertAlmostEqual(result["remaining_cycles"], 1.0)

    def test_projection_respects_custom_threshold(self) -> None:
        result = self.service.estimate_health(base_request(end_of_life_soh=0.85))
        self.assertEqual(result["projection_status"], "projected")
        self.assertAlmostEqual(result["remaining_cycles"], 0.5)

    def test_latest_soh_at_threshold_is_end_of_life(self) -> None:
        payload = base_request(
            measurements=[
                {
                    "timestamp_s": 0,
                    "measured_capacity_ah": 100.0,
                    "cumulative_discharge_ah": 0.0,
                },
                {
                    "timestamp_s": 100,
                    "measured_capacity_ah": 80.0,
                    "cumulative_discharge_ah": 200.0,
                },
            ]
        )
        result = self.service.estimate_health(payload)
        self.assertEqual(result["projection_status"], "end_of_life")
        self.assertEqual(result["remaining_cycles"], 0)

    def test_latest_soh_below_threshold_is_end_of_life(self) -> None:
        payload = base_request(
            measurements=[
                {
                    "timestamp_s": 0,
                    "measured_capacity_ah": 100.0,
                    "cumulative_discharge_ah": 0.0,
                },
                {
                    "timestamp_s": 100,
                    "measured_capacity_ah": 70.0,
                    "cumulative_discharge_ah": 300.0,
                },
            ]
        )
        result = self.service.estimate_health(payload)
        self.assertEqual(result["projection_status"], "end_of_life")
        self.assertEqual(result["remaining_cycles"], 0)

    def test_no_soh_drop_is_insufficient_trend(self) -> None:
        payload = base_request(
            measurements=[
                {
                    "timestamp_s": 0,
                    "measured_capacity_ah": 95.0,
                    "cumulative_discharge_ah": 0.0,
                },
                {
                    "timestamp_s": 100,
                    "measured_capacity_ah": 95.0,
                    "cumulative_discharge_ah": 100.0,
                },
            ]
        )
        result = self.service.estimate_health(payload)
        self.assertEqual(result["projection_status"], "insufficient_trend")
        self.assertIsNone(result["remaining_cycles"])

    def test_zero_cycle_span_is_insufficient_trend(self) -> None:
        payload = base_request(
            measurements=[
                {
                    "timestamp_s": 0,
                    "measured_capacity_ah": 100.0,
                    "cumulative_discharge_ah": 50.0,
                },
                {
                    "timestamp_s": 100,
                    "measured_capacity_ah": 90.0,
                    "cumulative_discharge_ah": 50.0,
                },
            ]
        )
        result = self.service.estimate_health(payload)
        self.assertEqual(result["projection_status"], "insufficient_trend")
        self.assertIsNone(result["remaining_cycles"])

    def test_soh_growth_is_insufficient_trend(self) -> None:
        payload = base_request(
            measurements=[
                {
                    "timestamp_s": 0,
                    "measured_capacity_ah": 90.0,
                    "cumulative_discharge_ah": 0.0,
                },
                {
                    "timestamp_s": 100,
                    "measured_capacity_ah": 95.0,
                    "cumulative_discharge_ah": 100.0,
                },
            ]
        )
        result = self.service.estimate_health(payload)
        self.assertEqual(result["projection_status"], "insufficient_trend")
        self.assertIsNone(result["remaining_cycles"])

    def test_threshold_of_zero_requires_zero_soh(self) -> None:
        payload = base_request(
            end_of_life_soh=0.0,
            measurements=[
                {
                    "timestamp_s": 0,
                    "measured_capacity_ah": 100.0,
                    "cumulative_discharge_ah": 0.0,
                },
                {
                    "timestamp_s": 100,
                    "measured_capacity_ah": 90.0,
                    "cumulative_discharge_ah": 100.0,
                },
            ],
        )
        result = self.service.estimate_health(payload)
        self.assertEqual(result["projection_status"], "projected")
        self.assertAlmostEqual(result["remaining_cycles"], 9.0)

    def test_successful_call_does_not_modify_input(self) -> None:
        payload = base_request()
        snapshot = json.loads(json.dumps(payload))
        self.service.estimate_health(payload)
        self.assertEqual(payload, snapshot)


class HealthValidationTest(unittest.TestCase):
    def setUp(self) -> None:
        self.service = Service()

    def assert_code(self, payload, code, status=422):
        with self.assertRaises(ApiError) as ctx:
            self.service.estimate_health(payload)
        self.assertEqual(ctx.exception.code, code)
        self.assertEqual(ctx.exception.status, status)

    def test_non_object_payload_is_invalid_json(self) -> None:
        for payload in (None, [], "text", 5):
            self.assert_code(payload, "invalid_json", status=400)

    def test_nominal_capacity_rules(self) -> None:
        self.assert_code(base_request(nominal_capacity_ah=None), "invalid_nominal_capacity")
        self.assert_code(base_request(nominal_capacity_ah=0), "invalid_nominal_capacity")
        self.assert_code(base_request(nominal_capacity_ah=-1.0), "invalid_nominal_capacity")
        self.assert_code(base_request(nominal_capacity_ah=True), "invalid_nominal_capacity")
        self.assert_code(base_request(nominal_capacity_ah="x"), "invalid_nominal_capacity")
        self.assert_code(
            base_request(nominal_capacity_ah=float("nan")),
            "invalid_nominal_capacity",
        )
        self.assert_code(
            {k: v for k, v in base_request().items() if k != "nominal_capacity_ah"},
            "invalid_nominal_capacity",
        )

    def test_measurements_rules(self) -> None:
        self.assert_code(base_request(measurements=[]), "invalid_measurements")
        self.assert_code(
            base_request(measurements=[base_request()["measurements"][0]]),
            "invalid_measurements",
        )
        self.assert_code(base_request(measurements="x"), "invalid_measurements")
        self.assert_code(base_request(measurements=None), "invalid_measurements")
        self.assert_code(base_request(measurements=[1, 2]), "invalid_measurements")

    def test_end_of_life_soh_rules(self) -> None:
        self.assert_code(base_request(end_of_life_soh=-0.01), "invalid_end_of_life_soh")
        self.assert_code(base_request(end_of_life_soh=1.01), "invalid_end_of_life_soh")
        self.assert_code(base_request(end_of_life_soh="x"), "invalid_end_of_life_soh")
        self.assert_code(
            base_request(end_of_life_soh=float("inf")), "invalid_end_of_life_soh"
        )

    def test_timestamp_rules(self) -> None:
        missing = [
            {"measured_capacity_ah": 100.0, "cumulative_discharge_ah": 0.0},
            {"measured_capacity_ah": 90.0, "cumulative_discharge_ah": 100.0},
        ]
        self.assert_code(base_request(measurements=missing), "invalid_timestamp")
        non_finite = [
            {
                "timestamp_s": 0,
                "measured_capacity_ah": 100.0,
                "cumulative_discharge_ah": 0.0,
            },
            {
                "timestamp_s": float("inf"),
                "measured_capacity_ah": 90.0,
                "cumulative_discharge_ah": 100.0,
            },
        ]
